# Keeps track of how IDs (and other unique keys) in an export translate into
# the account they are imported into. IDs are kept as they are whenever they're
# free, so moving an account between instances preserves them. When an ID is
# already taken (for example, when importing back into the same instance), a
# new one is generated that keeps the original timestamp, so records sort the
# same way they did before.
class Account::DataTransfer::IdMap
  def initialize
    @ids = {}
  end

  def register(model, ids)
    ids.each_slice(1000) do |batch|
      taken = model.unscoped.where(id: batch).pluck(:id).to_set

      batch.each do |id|
        @ids[id] ||= taken.include?(id) ? regenerate(id) : id
      end
    end
  end

  def []=(old_id, new_id)
    @ids[old_id] = new_id
  end

  def [](old_id)
    @ids.fetch(old_id, old_id)
  end

  def include?(old_id)
    @ids.key?(old_id)
  end

  def translate(value)
    case value
    when String then self[value]
    when Array  then value.map { |item| translate(item) }
    when Hash   then value.transform_values { |item| translate(item) }
    else value
    end
  end

  private
    def regenerate(id)
      timestamp = ActiveRecord::Type::Uuid.base36_to_hex(id).first(12)
      random = ActiveRecord::Type::Uuid.base36_to_hex(ActiveRecord::Type::Uuid.generate).from(12)

      ActiveRecord::Type::Uuid.hex_to_base36(timestamp + random)
    end
end
EOF

